//! The outputs written from the tokens, one per toolkit, where each is kept, and checking that the
//! checked-in ones are current.
//!
//! Every output is a [`Target`]: a file, where it is [`Kept`], and a pure function from the tokens
//! to its text. Writing, building, checking for staleness and the test that fails on a stale file
//! all go through [`targets`], so an output added there is generated, and guarded, from that
//! commit on.
//!
//! An output is generated where it is consumed, so two branches that change the tokens never touch
//! the same generated file: a crate's build script writes its Rust module ([`Kept::OutDir`]), and
//! the Nix build writes the QML, the configs and the Lua ([`Kept::Built`]). Only a file a program
//! reads straight from the checkout, outside any build, is checked in ([`Kept::Committed`]).
//!
//! # Owns
//!
//! - The list of outputs, where each is kept, and comparing or replacing each one on disk.
//!
//! # Not here
//!
//! - What an output says: each target's own module ([`crate::rust`], [`crate::qml`],
//!   [`crate::terminal`], [`crate::boot`], [`crate::neon`], [`crate::cursor`], [`crate::hypr`]).

use std::fs;
use std::io;
use std::path::Path;
use std::path::PathBuf;

use crate::boot::GrubTheme;
use crate::boot::PlymouthScript;
use crate::boot::PlymouthTheme;
use crate::cursor::CursorTokens;
use crate::hypr::HyprTokens;
use crate::model::Tokens;
use crate::neon::KoboNeon;
use crate::qml::QmlSymbols;
use crate::qml::QmlTokens;
use crate::rust::RustModule;
use crate::terminal::OUTPUTS;

/// Where a generated file is kept.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Kept {
    /// Checked in, and checked for staleness: a program reads it from the checkout outside any
    /// build (the boot screens' files, which `system/` installs as root), or it is a hand-written
    /// file with a generated block in it.
    Committed,
    /// Git ignores it. The Nix build writes it ([`build`]) for the packages and the home that read
    /// it; `kubaos-tokens write` writes it into a checkout, for the tools that read one.
    Built,
    /// The crate's build script writes it into its `OUT_DIR` ([`crate::build_script`]), and the
    /// crate's source file at [`Target::path`] includes it.
    OutDir,
}

/// The lines a [`Kept::Built`] output opens with, each after its comment marker.
pub const BUILT_HEADER: [&str; 2] = [
    "@generated by `kubaos-tokens` from `design/tokens.toml` where it is built: the Nix build, or",
    "`just tokens` in a checkout. Git ignores it: change the tokens, never this file.",
];

/// The lines a [`Kept::OutDir`] output opens with, each after its comment marker.
pub const OUT_DIR_HEADER: [&str; 2] = [
    "@generated by `kubaos-tokens` from `design/tokens.toml`, by the crate's build script, into its",
    "`OUT_DIR`. Change the tokens, never this file.",
];

/// One generated file.
pub trait Target: Sync {
    /// Where the file lives, relative to the repo's root. For a [`Kept::OutDir`] output, the
    /// source file that includes it, whose name it takes in `OUT_DIR`.
    fn path(&self) -> &'static str;

    /// Where the file is kept.
    fn kept(&self) -> Kept;

    /// The file's whole text for `tokens`, reading any drawing it embeds from the repo at `root`.
    ///
    /// # Errors
    ///
    /// When a file the output embeds can't be read.
    fn render(&self, tokens: &Tokens, root: &Path) -> io::Result<String>;
}

/// The toolkits' and the boot's outputs: `kubaos-ui`'s module, `KubaOS.Components`' singletons,
/// Plymouth's script and theme, GRUB's theme, Kōbō's neon, `kubaos-cursor`'s tokens and Hyprland's.
pub static TARGETS: &[&dyn Target] = &[
    &RustModule,
    &QmlTokens,
    &QmlSymbols,
    &PlymouthScript,
    &PlymouthTheme,
    &GrubTheme,
    &KoboNeon,
    &CursorTokens,
    &HyprTokens,
];

/// Every output `kubaos-tokens` writes: the toolkits', then the terminals' ([`OUTPUTS`]).
pub fn targets() -> impl Iterator<Item = &'static dyn Target> {
    TARGETS
        .iter()
        .copied()
        .chain(OUTPUTS.iter().map(|output| output as &dyn Target))
}

/// The checked-in output at `path` doesn't match the tokens.
#[derive(Debug)]
pub struct Stale {
    pub path: PathBuf,
}

/// Each checked-in output under `root` whose text differs from what `tokens` render to, or that is
/// missing. Every other output is rendered too, so one that can't be fails here as well.
///
/// # Errors
///
/// When an output exists but can't be read, or a file an output embeds can't be.
pub fn stale(root: &Path, tokens: &Tokens) -> io::Result<Vec<Stale>> {
    let mut found = Vec::new();
    for target in targets() {
        let text = target.render(tokens, root)?;
        if target.kept() != Kept::Committed {
            continue;
        }
        let path = root.join(target.path());
        if read(&path)?.as_deref() != Some(text.as_str()) {
            found.push(Stale { path });
        }
    }
    Ok(found)
}

/// Writes every output a checkout keeps, the checked-in ones and the ones git ignores, under `root`
/// where it differs from what `tokens` render to, and returns the paths it wrote.
///
/// # Errors
///
/// When an output can't be read or written.
pub fn write(root: &Path, tokens: &Tokens) -> io::Result<Vec<PathBuf>> {
    let mut written = Vec::new();
    for target in targets().filter(|target| target.kept() != Kept::OutDir) {
        let path = root.join(target.path());
        let text = target.render(tokens, root)?;
        if read(&path)?.as_deref() == Some(text.as_str()) {
            continue;
        }
        put(&path, &text)?;
        written.push(path);
    }
    Ok(written)
}

/// Writes every [`Kept::Built`] output of the repo at `root` under `out`, at its path in the repo,
/// and returns the paths it wrote.
///
/// # Errors
///
/// When a file an output embeds can't be read, or an output can't be written.
pub fn build(root: &Path, tokens: &Tokens, out: &Path) -> io::Result<Vec<PathBuf>> {
    let mut written = Vec::new();
    for target in targets().filter(|target| target.kept() == Kept::Built) {
        let path = out.join(target.path());
        put(&path, &target.render(tokens, root)?)?;
        written.push(path);
    }
    Ok(written)
}

/// Writes `text` to `path`, making its directory first.
fn put(path: &Path, text: &str) -> io::Result<()> {
    if let Some(dir) = path.parent() {
        fs::create_dir_all(dir)?;
    }
    fs::write(path, text)
}

/// The file's text, or `None` when there is no file.
fn read(path: &Path) -> io::Result<Option<String>> {
    match fs::read_to_string(path) {
        Ok(text) => Ok(Some(text)),
        Err(err) if err.kind() == io::ErrorKind::NotFound => Ok(None),
        Err(err) => Err(err),
    }
}
